// Format the response
const claudeResponse = $input.item.json;
const metadata = $('Process Feedback Request').item.json.metadata;
const feedbackType = $('Process Feedback Request').item.json.feedback_type;

let formattedResponse = {
  success: true,
  feedback_type: feedbackType,
  analysis: claudeResponse.response || claudeResponse,
  metadata: metadata,
  timestamp: new Date().toISOString()
};

// Add specific formatting based on feedback type
if (feedbackType === 'sentiment_analysis') {
  formattedResponse.quick_summary = {
    sentiment: 'Analyzed',
    recommendation: 'Review full analysis'
  };
} else if (feedbackType === 'complaint_handler') {
  formattedResponse.priority = 'Requires attention';
  formattedResponse.action_needed = true;
}

return { json: formattedResponse };
